// admin.js-এর SEED_MAP / CONTENT_ORDER / runSeed()-এর packing-এর প্রতিলিপি (js/admin.js পড়ে tests/contract.test.mjs এর সাথে মিলিয়ে দেখে)
const SEED_MAP = { services: seed.services, portfolio: seed.portfolioItems, caseStudies: seed.caseStudies, testimonials: seed.testimonials, team: seed.team, stats: seed.stats, pricingPlans: seed.pricingPlans, faqItems: seed.faqItems };
export const CONTENT_ORDER = Object.keys(SEED_MAP);
export const MAX_PER_BATCH = 15;
export function seedChunks(types, withSettings = true) {
  const batches = []; let cur = [];
  const room = (count) => { if (cur.length && cur.length + count > MAX_PER_BATCH) { batches.push(cur); cur = []; } };
  for (const key of types) {
    const items = SEED_MAP[key]; room(items.length);
    items.forEach((item, i) => cur.push({ op: "set", path: `${P}${key}/seed_${i}`, data: item }));
  }
  if (withSettings) { room(1); cur.push({ op: "set", path: P + "settings/site", data: seed.defaultSettings }); }
  if (cur.length) batches.push(cur);
  if (batches.some((b) => b.length > MAX_PER_BATCH)) throw new Error("seed chunk exceeds MAX_PER_BATCH");
  return batches;
}

